mapper.select:
SELECT ubd.id, ubd.user_id, ubd.agent_name as agentName, ubd.busi_type as busiType, ubd.channel, ubd.form_user_id, ubd.invite_code_status, u.mobile, ubd.original_amount, ubd.remarks, ubd.salesman_name, ubd.salesman_id, ubd.status, ubd.stream_id, ubd.transaction_amount, ubd.transaction_date, ubd.use_amount, ubd.create_date, ubd.update_date, u.mobile AS mobile, u.salesmanid, u.agent, u.biaoqian FROM user_balance_detail ubd LEFT JOIN tb_user u ON ubd.user_id = u.id
AND u.biaoqian LIKE CONCAT('%', #{biaoqian}, '%')
AND u.biaoqian IS NOT NULL AND u.biaoqian != ''
AND (u.biaoqian IS NULL OR u.biaoqian = '')
AND ubd.busi_type = #{busiType}
AND ubd.transaction_date >= #{startTime}
AND ubd.transaction_date <= #{endTime}
AND (ubd.mobile LIKE CONCAT('%', #{mobile}, '%') OR u.mobile LIKE CONCAT('%', #{mobile}, '%'))
ORDER BY ubd.transaction_date DESC
